      snow += snowLayer(uv, 0.25) * 0.6;
      snow += snowLayer(uv, 0.5) * 0.7;
      snow += snowLayer(uv, 0.75) * 0.8;
      snow += snowLayer(uv, 1.0) * 1.0;
